public with sharing class ContactTriggerHandler {

    /**
     * Collects the set of Account Ids referenced by the given contacts.
     */
    private static Set<Id> collectAccountIds(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }

    /**
     * Single query to fetch the fields we need from Accounts, used by both
     * before-insert/update logic and after-insert logic. Caller decides which
     * fields are relevant.
     */
    private static Map<Id, Account> queryAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return new Map<Id, Account>();
        }
        return new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource, Phone FROM Account WHERE Id IN :accountIds]
        );
    }

    public static void beforeInsert(List<Contact> newContacts) {
        Set<Id> accountIds = collectAccountIds(newContacts);
        Map<Id, Account> accountsById = queryAccounts(accountIds);

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public static void beforeUpdate(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        Set<Id> accountIds = collectAccountIds(newContacts);
        Map<Id, Account> accountsById = queryAccounts(accountIds);

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            // LeadSource is only defaulted on insert in the original code.
        }
    }

    public static void afterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = collectAccountIds(newContacts);
        Map<Id, Account> accountsById = queryAccounts(accountIds);

        // Track which accounts already have a phone (either pre-existing or
        // already claimed by an earlier contact in this same trigger batch),
        // so only the first eligible contact per account (in trigger order)
        // sets the account phone - matching the original per-row behaviour.
        Set<Id> accountsWithPhone = new Set<Id>();
        for (Account a : accountsById.values()) {
            if (String.isNotBlank(a.Phone)) {
                accountsWithPhone.add(a.Id);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (!accountsWithPhone.contains(a.Id)) {
                a.Phone = c.Phone;
                accountsWithPhone.add(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
