public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        String normalisedBase = normaliseCode(baseCurrency);
        if (!isValidCode(normalisedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalisedQuote = normaliseCode(quote);
            if (!isValidCode(normalisedQuote)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            normalisedQuotes.add(normalisedQuote);
        }

        List<String> sortedQuotes = new List<String>(normalisedQuotes);
        sortedQuotes.sort();
        String symbolsParam = String.join(sortedQuotes, ',');

        String endpoint = NAMED_CREDENTIAL_ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalisedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        if (res.getStatusCode() == 503) {
            HttpRequest retryReq = new HttpRequest();
            retryReq.setEndpoint(endpoint);
            retryReq.setMethod('GET');
            retryReq.setHeader('Accept', 'application/json');
            res = http.send(retryReq);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate API returned status code ' + res.getStatusCode() + ': ' + res.getStatus()
            );
        }

        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        if (parsed == null || !parsed.containsKey('rates') || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response did not contain a valid rates object.');
        }

        Map<String, Object> ratesRaw = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : normalisedQuotes) {
            if (!ratesRaw.containsKey(quote) || ratesRaw.get(quote) == null) {
                throw new ExchangeRateException('No rate found for requested currency: ' + quote);
            }
            Object rawValue = ratesRaw.get(quote);
            Decimal rateValue;
            try {
                rateValue = (Decimal) rawValue;
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency: ' + quote);
            }
            result.put(quote, rateValue);
        }

        return result;
    }

    private static String normaliseCode(String code) {
        if (code == null) {
            return null;
        }
        return code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        if (code == null) {
            return false;
        }
        return CURRENCY_CODE_PATTERN.matcher(code).matches();
    }
}
