public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        // --- Basic parameter validation ---
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name must be provided.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // --- Resolve the SObjectType (case-insensitive) ---
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType targetType = globalDescribe.get(objectApiName.toLowerCase());
        if (targetType == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objDescribe = targetType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object "' + objectApiName + '".');
        }

        // Build a case-insensitive map of field name -> DescribeFieldResult
        Map<String, Schema.SObjectField> fieldTokensByLowerName = objDescribe.fields.getMap();
        Map<String, Schema.DescribeFieldResult> fieldDescribesByLowerName = new Map<String, Schema.DescribeFieldResult>();
        for (String lowerName : fieldTokensByLowerName.keySet()) {
            fieldDescribesByLowerName.put(lowerName, fieldTokensByLowerName.get(lowerName).getDescribe());
        }

        // --- Validate and resolve requested fields (dedupe case-insensitively, always include Id) ---
        Map<String, String> selectFieldsByLower = new Map<String, String>(); // lowerName -> actual API name to use in SOQL

        // Always select Id
        Schema.DescribeFieldResult idDescribe = fieldDescribesByLowerName.get('id');
        if (idDescribe == null || !idDescribe.isAccessible()) {
            throw new SearchException('You do not have access to the Id field.');
        }
        selectFieldsByLower.put('id', idDescribe.getName());

        for (String rawField : fields) {
            if (String.isBlank(rawField)) {
                throw new SearchException('Field names must not be blank.');
            }
            String lowerField = rawField.toLowerCase();
            Schema.DescribeFieldResult fd = fieldDescribesByLowerName.get(lowerField);
            if (fd == null) {
                throw new SearchException('Field "' + rawField + '" does not exist on object "' + objectApiName + '".');
            }
            if (!fd.isAccessible()) {
                throw new SearchException('You do not have access to field "' + rawField + '".');
            }
            selectFieldsByLower.put(lowerField, fd.getName());
        }

        // --- Validate filters and build WHERE clause ---
        List<String> whereConditions = new List<String>();
        List<Object> bindValues = new List<Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String rawFilterField : filters.keySet()) {
                if (String.isBlank(rawFilterField)) {
                    throw new SearchException('Filter field names must not be blank.');
                }
                String lowerFilterField = rawFilterField.toLowerCase();
                Schema.DescribeFieldResult fd = fieldDescribesByLowerName.get(lowerFilterField);
                if (fd == null) {
                    throw new SearchException('Filter field "' + rawFilterField + '" does not exist on object "' + objectApiName + '".');
                }
                if (!fd.isAccessible()) {
                    throw new SearchException('You do not have access to filter field "' + rawFilterField + '".');
                }
                if (!fd.isFilterable()) {
                    throw new SearchException('Filter field "' + rawFilterField + '" cannot be filtered.');
                }

                Object rawValue = filters.get(rawFilterField);
                String bindVarName = 'bindVar' + bindIndex;
                bindIndex++;

                whereConditions.add(fd.getName() + ' = :' + bindVarName);
                bindValues.add(bindVarName);
                bindValues.add(rawValue);
            }
        }

        // --- Validate orderByField ---
        String resolvedOrderByField = null;
        if (String.isNotBlank(orderByField)) {
            String lowerOrderBy = orderByField.toLowerCase();
            Schema.DescribeFieldResult fd = fieldDescribesByLowerName.get(lowerOrderBy);
            if (fd == null) {
                throw new SearchException('Order-by field "' + orderByField + '" does not exist on object "' + objectApiName + '".');
            }
            if (!fd.isAccessible()) {
                throw new SearchException('You do not have access to order-by field "' + orderByField + '".');
            }
            if (!fd.isSortable()) {
                throw new SearchException('Order-by field "' + orderByField + '" cannot be sorted.');
            }
            resolvedOrderByField = fd.getName();
        }

        // --- Build the SOQL string using bind variables for values (safe against injection) ---
        List<String> orderedSelectFields = new List<String>();
        // Keep Id first, then the rest in the order they were validated (excluding duplicate id)
        orderedSelectFields.add(selectFieldsByLower.get('id'));
        for (String lowerName : selectFieldsByLower.keySet()) {
            if (lowerName == 'id') {
                continue;
            }
            orderedSelectFields.add(selectFieldsByLower.get(lowerName));
        }

        String soql = 'SELECT ' + String.join(orderedSelectFields, ', ') +
                      ' FROM ' + objDescribe.getName();

        if (!whereConditions.isEmpty()) {
            soql += ' WHERE ' + String.join(whereConditions, ' AND ');
        }

        if (resolvedOrderByField != null) {
            soql += ' ORDER BY ' + resolvedOrderByField + ' ASC';
        }

        soql += ' LIMIT :maxRows';

        // --- Build bind map for Database.queryWithBinds ---
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer i = 0;
        while (i < bindValues.size()) {
            String varName = (String) bindValues[i];
            Object varValue = bindValues[i + 1];
            bindMap.put(varName, varValue);
            i += 2;
        }
        bindMap.put('maxRows', maxRows);

        try {
            return Database.queryWithBinds(soql, bindMap, AccessLevel.USER_MODE);
        } catch (Exception ex) {
            throw new SearchException('Error executing search: ' + ex.getMessage());
        }
    }
}
