public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Integer size = leads.size();
        Id[] insertedIdsArr = new Id[size];
        for (Integer i = 0; i < size; i++) {
            insertedIdsArr[i] = null;
        }

        // Track which indices are eligible for DML (not duplicate, not null)
        Boolean[] eligible = new Boolean[size];
        for (Integer i = 0; i < size; i++) {
            eligible[i] = true;
        }

        Set<String> seenEmails = new Set<String>();

        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertIndexes = new List<Integer>();

        for (Integer i = 0; i < size; i++) {
            Lead ld = leads[i];

            if (ld == null) {
                eligible[i] = false;
                continue;
            }

            String emailKey = null;
            if (ld.Email != null) {
                String trimmed = ld.Email.trim();
                if (trimmed.length() > 0) {
                    emailKey = trimmed.toLowerCase();
                }
            }

            if (emailKey != null) {
                if (seenEmails.contains(emailKey)) {
                    eligible[i] = false;
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                    continue;
                } else {
                    seenEmails.add(emailKey);
                }
            }

            if (ld.LeadSource == null || String.isBlank(ld.LeadSource)) {
                ld.LeadSource = 'Web';
            }

            toInsert.add(ld);
            toInsertIndexes.add(i);
        }

        if (!toInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(toInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer originalIndex = toInsertIndexes[j];

                if (sr.isSuccess()) {
                    insertedIdsArr[originalIndex] = sr.getId();
                    result.successCount++;
                } else {
                    List<String> msgs = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        msgs.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(msgs, '; '));
                }
            }
        }

        for (Integer i = 0; i < size; i++) {
            if (insertedIdsArr[i] != null) {
                result.insertedIds.add(insertedIdsArr[i]);
            }
        }

        return result;
    }
}
