    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object API name and field API name must be provided.');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = globalDescribe.get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = sObjType.getDescribe().fields.getMap();
        Schema.SObjectField sObjField = fieldMap.get(fieldApiName.toLowerCase());
        if (sObjField == null) {
            throw new PicklistServiceException('Field not found: ' + fieldApiName + ' on object ' + objectApiName);
        }

        Schema.DescribeFieldResult dfr = sObjField.getDescribe();
        Schema.DisplayType fieldType = dfr.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Option> result = new List<Option>();
        List<Schema.PicklistEntry> entries = dfr.getPicklistValues();
        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                result.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }

        return result;
    }
}
