public class AccountScoringJob implements Queueable {

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext ctx) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer batchSize = Math.min(200, accountIds.size());
        List<Id> currentBatch = new List<Id>();
        for (Integer i = 0; i < batchSize; i++) {
            currentBatch.add(accountIds[i]);
        }

        List<Id> remaining = new List<Id>();
        if (accountIds.size() > batchSize) {
            for (Integer i = batchSize; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :currentBatch
        ];

        for (Account acc : accountsToUpdate) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }
}
