```apex
public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point called from OpportunityTrigger.
     * Recomputes FB_Open_Pipeline__c and FB_Open_Opportunities__c on every
     * Account potentially affected by this DML (old and/or new AccountId),
     * always by re-querying the current state of Opportunities from the
     * database. This makes the logic correct no matter how many times it
     * runs in the same transaction, and regardless of which other DML
     * (Flow, Apex, test code) already touched these records.
     */
    public static void run(Map<Id, Opportunity> oldMap, Map<Id, Opportunity> newMap, Boolean isDelete) {
        Set<Id> accountIds = new Set<Id>();

        if (oldMap != null) {
            for (Opportunity o : oldMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }
        if (newMap != null) {
            for (Opportunity o : newMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    /**
     * Recomputes the two rollup fields for the given set of Account Ids
     * based on the current, authoritative state of Opportunities in the
     * database, and updates only the Accounts whose values actually changed.
     */
    private static void recalculate(Set<Id> accountIds) {
        Map<Id, AggregateResult> resultsByAccount = new Map<Id, AggregateResult>();

        for (AggregateResult ar : [
            SELECT AccountId acc, SUM(Amount) sumAmount, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            resultsByAccount.put((Id) ar.get('acc'), ar);
        }

        List<Account> existingAccounts = [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> toUpdate = new List<Account>();

        for (Account acct : existingAccounts) {
            AggregateResult ar = resultsByAccount.get(acct.Id);

            Decimal newPipeline = 0;
            Integer newCount = 0;

            if (ar != null) {
                Object sumObj = ar.get('sumAmount');
                Object cntObj = ar.get('cnt');
                newPipeline = sumObj == null ? 0 : (Decimal) sumObj;
                newCount = cntObj == null ? 0 : ((Integer) cntObj);
            }

            Decimal currentPipeline = acct.FB_Open_Pipeline__c == null ? 0 : acct.FB_Open_Pipeline__c;
            Integer currentCount = acct.FB_Open_Opportunities__c == null
                ? 0
                : acct.FB_Open_Opportunities__c.intValue();

            if (currentPipeline != newPipeline || currentCount != newCount) {
                acct.FB_Open_Pipeline__c = newPipeline;
                acct.FB_Open_Opportunities__c = newCount;
                toUpdate.add(acct);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
