public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Initialize every requested account with 0
        for (Id accId : accountIds) {
            result.put(accId, 0);
        }

        Date startOfYear = Date.newInstance(Date.today().year(), 1, 1);
        Date startOfNextYear = Date.newInstance(Date.today().year() + 1, 1, 1);

        List<AggregateResult> results = [
            SELECT AccountId acc, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate < :startOfNextYear
            GROUP BY AccountId
        ];

        for (AggregateResult ar : results) {
            Id accId = (Id) ar.get('acc');
            Decimal sum = (Decimal) ar.get('totalAmount');
            result.put(accId, sum == null ? 0 : sum);
        }

        return result;
    }
}
