public with sharing class StaleOpportunityCloser {

    /**
     * Closes (sets StageName = 'Closed Lost') every open opportunity whose
     * CloseDate is strictly before the given cutoff date.
     *
     * Uses a SOQL for loop in list form so that records are streamed from the
     * query cursor in chunks of 200, keeping heap usage flat regardless of
     * how many opportunities match. Each chunk is updated immediately, and
     * DML/SOQL governor limits are respected because at most 200 records are
     * held and updated at a time (well within the 10,000 record / 150 DML
     * statement limits for a single synchronous transaction, assuming a
     * reasonable nightly volume).
     *
     * @param cutoff opportunities with CloseDate < cutoff are closed;
     *               an opportunity closing exactly on cutoff stays open.
     * @return the total number of opportunities closed.
     */
    public static Integer closeStale(Date cutoff) {
        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
            AND CloseDate < :cutoff
            ORDER BY Id
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
