/**
 * Service class responsible for creating weekly pipeline review follow-up Tasks
 * for a batch of Opportunities.
 *
 * Bulk-safe: performs exactly one SOQL query and one DML statement regardless
 * of the number of Opportunity Ids passed in (handles the typical 150-250
 * per call, and well beyond that too).
 */
public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each Opportunity Id supplied.
     *
     * @param opportunityIds the Opportunity Ids coming out of the pipeline review
     * @return the set of Opportunity Ids for which a Task could NOT be created
     *         (either because the Opportunity could not be found/accessed, or
     *         because the Task insert was rejected, e.g. by a validation rule).
     *         Empty set when every Task was created successfully.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // De-duplicate while preserving a usable lookup, in case callers pass duplicates.
        Set<Id> uniqueIds = new Set<Id>(opportunityIds);

        // Single bulk query to get the data we need to build the Tasks.
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :uniqueIds
            ]
        );

        // Any requested Id that didn't come back from the query (deleted,
        // inaccessible, or simply not a valid Opportunity Id) can't get a Task.
        for (Id oppId : uniqueIds) {
            if (!oppsById.containsKey(oppId)) {
                failedOpportunityIds.add(oppId);
            }
        }

        if (oppsById.isEmpty()) {
            return failedOpportunityIds;
        }

        // Build the Tasks, keeping a parallel list of source Opportunity Ids so we
        // can map Database.insert results back to the Opportunity that spawned them.
        List<Task> tasksToInsert = new List<Task>();
        List<Id> sourceOpportunityIds = new List<Id>();

        Date followUpDate = Date.today().addDays(7);

        for (Opportunity opp : oppsById.values()) {
            Task t = new Task();
            t.WhatId = opp.Id;
            t.OwnerId = opp.OwnerId;
            t.Subject = 'Follow up: ' + opp.Name;
            t.ActivityDate = followUpDate;
            t.Status = 'Not Started';
            t.Priority = 'Normal';

            tasksToInsert.add(t);
            sourceOpportunityIds.add(opp.Id);
        }

        // allOrNone = false: a rejected Task (e.g. by a validation rule) must not
        // prevent the rest of the Tasks from being created.
        Database.SaveResult[] results = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(sourceOpportunityIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
```

