public class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /**
     * Entry point used by the trigger. Accepts the full set of Account Ids
     * whose Rating may need to be recalculated, and performs the work
     * asynchronously in a single future call per transaction to stay well
     * within governor limits even for large batches (e.g. 200 opportunities
     * from CPQ).
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Aggregate open opportunity amounts per account in one query.
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();

        for (Opportunity opp : [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
        ]) {
            openCountByAccount.put(
                opp.AccountId,
                (openCountByAccount.containsKey(opp.AccountId) ? openCountByAccount.get(opp.AccountId) : 0) + 1
            );

            Decimal amount = opp.Amount == null ? 0 : opp.Amount;
            Decimal currentMax = maxOpenAmountByAccount.get(opp.AccountId);
            if (currentMax == null || amount > currentMax) {
                maxOpenAmountByAccount.put(opp.AccountId, amount);
            }
        }

        // Determine the desired rating for every account in scope.
        Map<Id, String> desiredRatingByAccount = new Map<Id, String>();
        for (Id accId : accountIds) {
            Integer openCount = openCountByAccount.containsKey(accId) ? openCountByAccount.get(accId) : 0;

            if (openCount == 0) {
                desiredRatingByAccount.put(accId, RATING_COLD);
            } else {
                Decimal maxAmount = maxOpenAmountByAccount.get(accId);
                if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                    desiredRatingByAccount.put(accId, RATING_HOT);
                } else {
                    desiredRatingByAccount.put(accId, RATING_WARM);
                }
            }
        }

        // Only update accounts whose Rating actually needs to change.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            String desiredRating = desiredRatingByAccount.get(acc.Id);
            if (desiredRating != null && desiredRating != acc.Rating) {
                acc.Rating = desiredRating;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    /**
     * Convenience overload for callers that only have a single Account Id,
     * so existing call sites or tests written against the original signature
     * still compile and work.
     */
    public static void recalculate(Id accountId) {
        if (accountId == null) {
            return;
        }
        recalculate(new Set<Id>{ accountId });
    }
}
