public with sharing class LineItemDiscountHandler {

    /**
     * For every line with a null Discount, set it to the product's standard discount.
     * Lines that already have a Discount (including 0) are left untouched.
     *
     * Bulk-safe: PricingRules.standardDiscountFor is invoked at most once per distinct
     * Product2Id that actually needs a default, rather than once per line, so a 200-line
     * CPQ quote does not risk the SOQL governor limit.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        // Collect distinct product ids for lines that need a default discount.
        Set<Id> productIdsNeedingDefault = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDefault.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDefault.isEmpty()) {
            return;
        }

        // Cache one standard discount per distinct product, calling PricingRules exactly
        // as instructed, but only once per unique product id.
        Map<Id, Decimal> standardDiscountByProductId = new Map<Id, Decimal>();
        for (Id productId : productIdsNeedingDefault) {
            standardDiscountByProductId.put(productId, PricingRules.standardDiscountFor(productId));
        }

        // Apply the cached discount to each line that needs one.
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                line.Discount = standardDiscountByProductId.get(line.Product2Id);
            }
        }
    }
}
