/**
 * Queueable job that creates a single CSAT survey Task for one Case.
 *
 * Design notes:
 * - One job instance handles exactly one Case, as requested, so a failure
 *   creating a Task for one case (e.g. validation rule, required field)
 *   cannot affect any other case's survey task.
 * - Apex only allows a Queueable to enqueue 1 more Queueable from within
 *   itself (chaining), but allows up to 50 System.enqueueJob calls from a
 *   normal synchronous context (e.g. the trigger's transaction). Because
 *   agents can bulk-close well over 50 cases from a list view, and the
 *   nightly API job can close up to 200 at once, we cannot safely call
 *   System.enqueueJob once per case directly from the trigger for large
 *   batches - it would throw System.LimitException once more than 50
 *   cases are closed in the same transaction.
 *
 *   To keep the "one case = one job" contract from the spec while staying
 *   within governor limits, enqueueForCases() enqueues up to 50 jobs
 *   immediately from the trigger context. Any remaining case Ids are
 *   attached to the *last* job of that batch; when that job finishes
 *   processing its own case, it chains (enqueues) the next job for the
 *   next remaining case, which in turn carries the rest of the queue
 *   forward. This guarantees every case still gets its own isolated job,
 *   it just means jobs beyond the first 50 run slightly later, chained
 *   one after another, which is an acceptable trade-off for an
 *   asynchronous, best-effort survey step.
 */
public with sharing class CaseSurveyJob implements Queueable {

    private static final Integer MAX_ENQUEUE_PER_TRANSACTION = 50;

    private final Id caseId;

    // Any remaining case Ids this job is responsible for chaining onward
    // after it finishes processing its own caseId.
    private final List<Id> remainingCaseIds;

    public CaseSurveyJob(Id caseId) {
        this(caseId, new List<Id>());
    }

    public CaseSurveyJob(Id caseId, List<Id> remainingCaseIds) {
        this.caseId = caseId;
        this.remainingCaseIds = (remainingCaseIds != null)
            ? remainingCaseIds
            : new List<Id>();
    }

    /**
     * Entry point used by CaseTrigger. Enqueues one job per case, up to
     * the per-transaction limit. Any overflow is carried by the last
     * enqueued job and chained forward asynchronously.
     */
    public static void enqueueForCases(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        Integer total = caseIds.size();
        Integer immediateCount = Math.min(total, MAX_ENQUEUE_PER_TRANSACTION);

        for (Integer i = 0; i < immediateCount; i++) {
            Id currentCaseId = caseIds[i];

            // The very last job we enqueue in this transaction carries
            // any overflow beyond the first 50, so it can chain the rest.
            Boolean isLastImmediateJob = (i == immediateCount - 1);
            List<Id> overflow = new List<Id>();

            if (isLastImmediateJob && total > MAX_ENQUEUE_PER_TRANSACTION) {
                overflow = new List<Id>();
                for (Integer j = MAX_ENQUEUE_PER_TRANSACTION; j < total; j++) {
                    overflow.add(caseIds[j]);
                }
            }

            System.enqueueJob(new CaseSurveyJob(currentCaseId, overflow));
        }
    }

    public void execute(QueueableContext context) {
        try {
            createSurveyTaskForCase(this.caseId);
        } finally {
            // Chain the next overflow job regardless of whether this
            // job's own task creation succeeded, so one bad case can't
            // block the rest of the queue from being processed.
            chainNextIfNeeded();
        }
    }

    private void chainNextIfNeeded() {
        if (remainingCaseIds.isEmpty()) {
            return;
        }

        // Queueable chaining allows exactly one more enqueueJob call
        // from within an executing Queueable context.
        List<Id> nextRemaining = new List<Id>();
        Id nextCaseId = remainingCaseIds[0];

        for (Integer i = 1; i < remainingCaseIds.size(); i++) {
            nextRemaining.add(remainingCaseIds[i]);
        }

        System.enqueueJob(new CaseSurveyJob(nextCaseId, nextRemaining));
    }

    private void createSurveyTaskForCase(Id targetCaseId) {
        if (targetCaseId == null) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id = :targetCaseId
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];

        // Defensive re-check: by the time this async job runs the case
        // could theoretically have been reopened or lost its contact.
        // Only create the survey task if conditions still hold.
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }
}
