/**
 * Service responsible for emailing Opportunity owners a renewal reminder.
 *
 * Note on implementation: although the task describes "one Messaging.sendEmail
 * call per opportunity", Messaging.sendEmail is limited to 10 invocations per
 * transaction (Limits.getLimitEmailInvocations()). Calling it once per
 * opportunity would throw a LimitException as soon as more than 10
 * opportunities are passed in, and the job can pass up to 200. Instead we
 * build the full list of SingleEmailMessage objects and send them with a
 * single call to Messaging.sendEmail(List<Messaging.SingleEmailMessage>,
 * allOrNone = false). This still gives per-message isolation (one failing
 * email does not prevent the others from being sent) while remaining safely
 * bulkified and within governor limits.
 */
public with sharing class RenewalReminderService {

    /**
     * Sends a renewal reminder email to the owner of each given Opportunity.
     *
     * @param opportunityIds up to 200 Opportunity Ids whose renewal is due.
     * @return the number of emails that were sent successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId, Owner.Type
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            // setTargetObjectId requires a User Id. Opportunity.OwnerId can
            // theoretically be a Queue Id in some configurations; skip those
            // defensively so they don't blow up the whole send.
            if (opp.OwnerId == null || opp.Owner == null || opp.Owner.Type != 'User') {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);

            String closeDateString = opp.CloseDate != null
                ? opp.CloseDate.format()
                : 'an unspecified date';

            email.setPlainTextBody(
                'This is a reminder that the opportunity "' + opp.Name +
                '" is due for renewal on ' + closeDateString +
                '. Please review and take any necessary action.'
            );

            emails.add(email);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails, false);

        Integer successCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
