/**
 * Service class for setting a Contact's current employer (Organization Account)
 * via NPSP Affiliations, in compliance with the NPSP Household Account model.
 *
 * Relies on NPSP's own trigger handlers (TDTM) to:
 *  - demote any previously Current/Primary affiliation to Former (with EndDate = today)
 *  - update Contact.npsp__Primary_Affiliation__c to point to the new organization
 *
 * This class therefore only ever INSERTs the new Current/Primary Affiliation record
 * when needed; it never manually updates the Contact or manually closes out old
 * affiliations, avoiding conflicts with NPSP's automation and keeping DML/SOQL counts low.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: get each contact's current primary affiliation (if any), to detect no-ops.
        Map<Id, Id> currentPrimaryAccountByContactId = new Map<Id, Id>();
        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            currentPrimaryAccountByContactId.put(c.Id, c.npsp__Primary_Affiliation__c);
        }

        // Query 2: get existing Current + Primary affiliation records for these contacts,
        // so we know which ones NPSP will need to demote (for our own bookkeeping only;
        // we do not touch them directly) and, more importantly, so we never create a
        // duplicate affiliation record if one already exists for the target org
        // (even if, for some reason, it isn't marked Current/Primary on the Contact lookup).
        Map<Id, npe5__Affiliation__c> existingCurrentPrimaryAfflByContactId = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c affl : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Status__c = 'Current'
            AND npe5__Primary__c = true
        ]) {
            existingCurrentPrimaryAfflByContactId.put(affl.npe5__Contact__c, affl);
        }

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            Id currentPrimaryAccountId = currentPrimaryAccountByContactId.get(contactId);

            // No-op: organization is already the contact's primary affiliation.
            if (currentPrimaryAccountId == orgId) {
                continue;
            }

            // Also guard against a Current/Primary affiliation record already pointing
            // to this org (even if the Contact lookup is out of sync for some reason).
            npe5__Affiliation__c existing = existingCurrentPrimaryAfflByContactId.get(contactId);
            if (existing != null && existing.npe5__Organization__c == orgId) {
                continue;
            }

            npe5__Affiliation__c newAffl = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            );
            affiliationsToInsert.add(newAffl);
        }

        if (!affiliationsToInsert.isEmpty()) {
            // Single DML of our own. NPSP's Affiliation trigger handlers (TDTM) will:
            //  - mark any prior Current/Primary affiliation for the same contact as
            //    Former, non-primary, with npe5__EndDate__c = today
            //  - update Contact.npsp__Primary_Affiliation__c to this new Account
            insert affiliationsToInsert;
        }
    }
}
