public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id must not be null.');
            }

            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }

            gauIds.add(gauId);
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentage cannot exceed 100. Current total: ' + totalPercent);
        }

        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :gauIds]
        );

        if (gauMap.size() != gauIds.size()) {
            Set<Id> missing = new Set<Id>(gauIds);
            missing.removeAll(gauMap.keySet());
            throw new AllocationException('The following GAU Ids were not found: ' + missing);
        }

        for (npsp__General_Accounting_Unit__c gau : gauMap.values()) {
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU ' + gau.Name + ' (' + gau.Id + ') is not active.');
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            );
            newAllocations.add(alloc);
        }

        insert newAllocations;

        return newAllocations;
    }
}
