public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect opportunity Ids needed for validation
        Set<Id> oppIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                oppIds.add(req.opportunityId);
            }
        }

        // Query 1: Opportunities with primary contact and amount
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // Validate entire batch before any DML
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity Id and Contact Id are required.');
            }

            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }

            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact on opportunity ' + req.opportunityId
                );
            }

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive for contact ' + req.contactId);
            }

            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount exceeds opportunity amount for contact ' + req.contactId
                );
            }

            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is required for contact ' + req.contactId);
            }
        }

        // Query 2: Existing OpportunityContactRoles for the opp/contact pairs
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            contactIds.add(req.contactId);
        }

        Map<String, OpportunityContactRole> ocrByKey = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = ocr.OpportunityId + '_' + ocr.ContactId;
            // If multiple exist for same pair, prefer the first encountered;
            // we will update it below to guarantee exactly one role record logically used.
            if (!ocrByKey.containsKey(key)) {
                ocrByKey.put(key, ocr);
            }
        }

        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> keyToOcr = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '_' + req.contactId;
            OpportunityContactRole ocr = ocrByKey.get(key);
            if (ocr == null) {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(newOcr);
                keyToOcr.put(key, newOcr);
            } else {
                if (ocr.Role != req.role) {
                    ocr.Role = req.role;
                    ocrsToUpdate.add(ocr);
                }
                keyToOcr.put(key, ocr);
            }
        }

        // DML 1: insert new contact roles
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        // DML 2: update existing contact roles whose role changed
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        // Query 3: Existing partial soft credits for these opp/contact pairs
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            String key = psc.npsp__Opportunity__c + '_' + psc.npsp__Contact__c;
            pscByKey.put(key, psc);
        }

        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '_' + req.contactId;
            OpportunityContactRole ocr = keyToOcr.get(key);
            npsp__Partial_Soft_Credit__c psc = pscByKey.get(key);

            if (psc == null) {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                );
                pscsToInsert.add(newPsc);
            } else {
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = ocr.Id;
                pscsToUpdate.add(psc);
            }
        }

        // DML 3: insert new soft credits
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }
        // DML 4: update existing soft credits
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
