```apex
/**
 * Service class that determines which of a given set of record Ids the running
 * user actually has edit access to, by consulting UserRecordAccess.
 *
 * UserRecordAccess reflects the full access computation (object permissions,
 * field level security is not relevant here, ownership, sharing rules,
 * role hierarchy, teams, Modify All / View All, etc.) so we do not need to
 * reimplement any of that logic ourselves - we just query it safely in bulk.
 */
public with sharing class RecordAccessService {

    // UserRecordAccess only supports querying a bounded number of RecordIds
    // in a single WHERE ... IN (...) clause efficiently. We chunk to stay
    // well within governor limits and Salesforce's own recommended limits
    // for this object (commonly documented as up to 200 Ids per query).
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // De-duplicate and drop nulls defensively; also preserves a stable
        // iteration order for chunking.
        List<Id> cleanIds = new List<Id>();
        Set<Id> seen = new Set<Id>();
        for (Id recId : recordIds) {
            if (recId != null && !seen.contains(recId)) {
                seen.add(recId);
                cleanIds.add(recId);
            }
        }

        if (cleanIds.isEmpty()) {
            return result;
        }

        Id currentUserId = UserInfo.getUserId();

        Integer totalChunks = Integer.valueOf(
            Math.ceil(cleanIds.size() / (Decimal) CHUNK_SIZE)
        );

        // Guard against exceeding the caller's stated budget of 20 SOQL
        // queries for up to 2,000 Ids. With CHUNK_SIZE = 200, 2,000 Ids
        // requires exactly 10 queries, well within the limit.
        if (totalChunks > Limits.getLimitQueries() - Limits.getQueries()) {
            throw new RecordAccessServiceException(
                'Not enough remaining SOQL query budget to resolve edit access for ' +
                cleanIds.size() + ' records.'
            );
        }

        for (Integer start = 0; start < cleanIds.size(); start += CHUNK_SIZE) {
            Integer endExclusive = Math.min(start + CHUNK_SIZE, cleanIds.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < endExclusive; i++) {
                chunk.add(cleanIds[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }

    public class RecordAccessServiceException extends Exception {}
}
